CREATE TYPE public.app_role AS ENUM ('admin','researcher','user');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,role public.app_role NOT NULL,UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_role_read ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE TABLE public.instruments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),symbol text NOT NULL UNIQUE CHECK(symbol IN ('EURUSD','GBPUSD','USDJPY','XAUUSD')),name text NOT NULL,asset_class text NOT NULL);
GRANT SELECT ON public.instruments TO anon,authenticated; GRANT ALL ON public.instruments TO service_role;
ALTER TABLE public.instruments ENABLE ROW LEVEL SECURITY;
CREATE POLICY instrument_catalog ON public.instruments FOR SELECT TO anon,authenticated USING(true);
CREATE TABLE public.dataset_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,symbol text NOT NULL CHECK(symbol IN ('EURUSD','GBPUSD','USDJPY','XAUUSD')),timeframe text NOT NULL CHECK(timeframe IN ('M1','M5','M15','M30','H1','H4','D1')),filename text NOT NULL,row_count integer NOT NULL CHECK(row_count>0),content_hash text NOT NULL,start_at timestamptz NOT NULL,end_at timestamptz NOT NULL,provenance text NOT NULL DEFAULT 'User-uploaded historical CSV',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,content_hash,symbol,timeframe));
GRANT SELECT,INSERT ON public.dataset_versions TO authenticated; GRANT ALL ON public.dataset_versions TO service_role;
ALTER TABLE public.dataset_versions ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_dataset_read ON public.dataset_versions FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY own_dataset_insert ON public.dataset_versions FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());
CREATE TABLE public.market_bars (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,dataset_id uuid NOT NULL REFERENCES public.dataset_versions(id) ON DELETE CASCADE,symbol text NOT NULL,timeframe text NOT NULL,timestamp timestamptz NOT NULL,open double precision NOT NULL,high double precision NOT NULL,low double precision NOT NULL,close double precision NOT NULL,volume double precision, CHECK(open>0 AND low>0 AND close>0 AND high>=greatest(open,close,low) AND low<=least(open,close) AND (volume IS NULL OR volume>=0)),UNIQUE(dataset_id,timestamp));
GRANT SELECT,INSERT ON public.market_bars TO authenticated; GRANT ALL ON public.market_bars TO service_role;
ALTER TABLE public.market_bars ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_bar_read ON public.market_bars FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY own_bar_insert ON public.market_bars FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.dataset_versions d WHERE d.id=dataset_id AND d.user_id=auth.uid()));
CREATE INDEX market_bars_lookup ON public.market_bars(user_id,symbol,timeframe,timestamp DESC);
CREATE TABLE public.user_settings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL UNIQUE,timezone text NOT NULL DEFAULT 'UTC',default_timeframe text NOT NULL DEFAULT 'H1',risk_per_trade numeric NOT NULL DEFAULT 1 CHECK(risk_per_trade>0 AND risk_per_trade<=5),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.user_settings TO authenticated; GRANT ALL ON public.user_settings TO service_role;
ALTER TABLE public.user_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_settings ON public.user_settings FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.model_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,version text NOT NULL,status text NOT NULL DEFAULT 'candidate' CHECK(status IN ('candidate','validated','production','retired')),dataset_id uuid REFERENCES public.dataset_versions(id),metrics jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,version));
GRANT SELECT ON public.model_versions TO authenticated; GRANT ALL ON public.model_versions TO service_role;
ALTER TABLE public.model_versions ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_models ON public.model_versions FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.model_predictions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,model_id uuid NOT NULL REFERENCES public.model_versions(id),symbol text NOT NULL,timeframe text NOT NULL,bullish double precision NOT NULL CHECK(bullish BETWEEN 0 AND 1),bearish double precision NOT NULL CHECK(bearish BETWEEN 0 AND 1),neutral double precision NOT NULL CHECK(neutral BETWEEN 0 AND 1),decision text NOT NULL CHECK(decision IN ('BUY','SELL','WAIT')),regime text NOT NULL,feature_context jsonb NOT NULL,generated_at timestamptz NOT NULL,expires_at timestamptz NOT NULL,CHECK(abs(bullish+bearish+neutral-1)<0.0001),CHECK(expires_at>generated_at),UNIQUE(user_id,model_id,symbol,timeframe,generated_at));
GRANT SELECT ON public.model_predictions TO authenticated; GRANT ALL ON public.model_predictions TO service_role;
ALTER TABLE public.model_predictions ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_predictions ON public.model_predictions FOR SELECT TO authenticated USING(user_id=auth.uid());
DO $$ DECLARE table_name text; BEGIN FOREACH table_name IN ARRAY ARRAY['broker_symbol_mappings','market_data_sources','market_ticks','market_features','market_regimes','pattern_events','training_runs','prediction_outcomes','model_evaluations','model_health','signal_records','strategy_definitions','strategy_regime_performance','risk_events','trade_intents','orders','executions','positions','account_snapshots','simulator_test_runs','simulator_test_results','indicator_exports','data_quality_checks','system_events','audit_logs'] LOOP EXECUTE format('CREATE TABLE public.%I (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,dataset_id uuid REFERENCES public.dataset_versions(id),model_id uuid REFERENCES public.model_versions(id),context jsonb NOT NULL DEFAULT ''{}'',created_at timestamptz NOT NULL DEFAULT now())',table_name); EXECUTE format('GRANT SELECT ON public.%I TO authenticated',table_name); EXECUTE format('GRANT ALL ON public.%I TO service_role',table_name); EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',table_name); EXECUTE format('CREATE POLICY own_read ON public.%I FOR SELECT TO authenticated USING(user_id=auth.uid())',table_name); EXECUTE format('CREATE INDEX ON public.%I(user_id,created_at DESC)',table_name); END LOOP; END $$;
COMMENT ON TABLE public.orders IS 'Reserved for a separately authorized future release. No execution API exists.';
COMMENT ON TABLE public.executions IS 'Reserved; AFI is signals-only.';
CREATE FUNCTION public.import_historical_dataset(p_symbol text,p_timeframe text,p_filename text,p_hash text,p_bars jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE dataset uuid; owner uuid:=auth.uid(); BEGIN IF owner IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF; IF jsonb_array_length(p_bars)<2 OR jsonb_array_length(p_bars)>10000 THEN RAISE EXCEPTION 'Dataset must contain 2 to 10000 bars'; END IF; INSERT INTO public.dataset_versions(user_id,symbol,timeframe,filename,row_count,content_hash,start_at,end_at) SELECT owner,p_symbol,p_timeframe,p_filename,jsonb_array_length(p_bars),p_hash,min((b->>'timestamp')::timestamptz),max((b->>'timestamp')::timestamptz) FROM jsonb_array_elements(p_bars) b RETURNING id INTO dataset; INSERT INTO public.market_bars(user_id,dataset_id,symbol,timeframe,timestamp,open,high,low,close,volume) SELECT owner,dataset,p_symbol,p_timeframe,(b->>'timestamp')::timestamptz,(b->>'open')::double precision,(b->>'high')::double precision,(b->>'low')::double precision,(b->>'close')::double precision,(b->>'volume')::double precision FROM jsonb_array_elements(p_bars) b; RETURN dataset; END $$;
REVOKE ALL ON FUNCTION public.import_historical_dataset(text,text,text,text,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.import_historical_dataset(text,text,text,text,jsonb) TO authenticated;